                clientIp));
    }

    private void enforceNotInViewAsOverlay(
            AuthenticatedPrincipal principal,
            String actionName,
            String resourceId,
            String correlationId,
            String clientIp) {
        if (principal.readOnlyOverlay()) {
            String details = "{\"reason\":\"view_as_read_only_overlay\",\"action\":\"" + actionName + "\"}";
