                    principal, "AUTHZ_DENIED", actionName, resourceId, "DENIED",
                    correlationId, details, clientIp);
            recordAuditWithOutcome(
                    principal, "VIEW_AS_MUTATION_BLOCKED", actionName, resourceId, "DENIED",
                    correlationId, details, clientIp);
            ContractGuards.requireNotInViewAsOverlay(true);
        }
    }

